BEGIN TRANSACTION;
CREATE TABLE "tickets" (
"Status" TEXT,
  "Ticket ID" INTEGER,
  "Priority" TEXT,
  "Source" TEXT,
  "Topic" TEXT,
  "Agent Group" TEXT,
  "Agent Name" TEXT,
  "Created time" TEXT,
  "Expected SLA to resolve" TEXT,
  "Expected SLA to first response" TEXT
);
CREATE INDEX idx_ticket_id ON tickets("Ticket ID");
COMMIT;
